// spec: specs/companion.md
// seed: tests/seed.parent-auto.spec.ts
// Ребёнок QA-R2-V — в слоте parent-auto (постоянно в режиме ребёнка, решение 08.11 #8ca267); parent.json не используется.
// Слот может быть ещё не в режиме ребёнка (первый прогон) или уже в нём — goChildHome справляется с обоими. В конце сессия слота сохраняется (saveSlot).

import { test, expect, Page } from '@playwright/test';
import { CHILD_SLOTS, goChildHome, saveSlot, slotState } from '../child-slot.helpers';

const KID = CHILD_SLOTS['QA-R2-V'];
const CHILD_ID = KID.childId;

test.use({ storageState: slotState(KID) });

// refresh-токен Supabase одноразовый — сохранить сессию слота обратно после каждого теста
test.afterEach(async ({ page }) => {
  await saveSlot(page.context(), KID);
});

async function visibleText(page: Page) {
  return page.locator('body').innerText();
}

// Общие проверки текста ארנבת (логотип alt «Benjico.Ai» не входит в innerText)
function expectRabbitTexts(text: string) {
  expect(text).not.toMatch(/בנג[׳']?י/);
  expect(text).not.toMatch(/אני מקשיב(?!ה)/);
  expect(text).not.toMatch(/אני קורא(?!ת)/);
  expect(text).not.toContain('להארנבת');
}

test.describe('Тексты спутника на экранах ребёнка — десктоп (#b3210e)', () => {
  test('QA-R2-V (ארנבת): תרגול קריאה — «הארנבת תקשיב לך», «אני מקשיבה», «עכשיו אני קוראת», голос rabbit @desktop @data #b3210e', async ({ page }) => {
    await page.setViewportSize({ width: 1440, height: 900 });

    // 1. Записывать rpc/child_profile и POST /functions/v1/tts
    const companions: unknown[] = [];
    const ttsBodies: { voice?: string; text?: string }[] = [];
    page.on('response', async (resp) => {
      if (!resp.url().includes('rpc/child_profile')) return;
      try {
        const body = await resp.json();
        const row = Array.isArray(body) ? body[0] : body;
        companions.push(row?.companion);
      } catch {
        /* не JSON */
      }
    });
    page.on('request', (req) => {
      if (req.method() !== 'POST' || !req.url().includes('/functions/v1/tts')) return;
      try {
        ttsBodies.push(JSON.parse(req.postData() ?? '{}'));
      } catch {
        ttsBodies.push({});
      }
    });
    const ttsResponse = () =>
      page.waitForResponse((r) => r.request().method() === 'POST' && r.url().includes('/functions/v1/tts'));

    // 2. Дом ребёнка QA-R2-V в слоте parent-auto: передача «QA-R2-V, בואו נתחיל!» (первый прогон) или закрыть гейт (слот уже в режиме ребёнка)
    await goChildHome(page, KID);
    await expect(page).toHaveURL(new RegExp(`/${CHILD_ID}/home`));

    // Предусловие: companion === "rabbit"
    await expect
      .poll(() => companions.at(-1), {
        message: 'Предусловие: rpc/child_profile должен вернуть companion === "rabbit" у QA-R2-V',
      })
      .toBe('rabbit');

    // «תרגול קריאה» -> первая карточка отрывка. Кнопка на доме открывает последний отрывок
    // («המשך מהנקודה האחרונה»), поэтому список историй открывается по /reading/pick.
    await page.goto(`/${CHILD_ID}/reading/pick`);
    const ttsFirst = ttsResponse();
    await page.getByRole('list', { name: 'סיפורים לקריאה' }).getByRole('button').first().click();
    await expect(page).toHaveURL(new RegExp(`/${CHILD_ID}/reading/[^/]+/read`));

    // Экран чтения — осмотреть, дождаться ответа tts
    await expect(page.getByText('הארנבת תקשיב לך דרך המיקרופון')).toBeVisible();
    await expect(page.getByText(/אני מקשיבה\.?$/)).toBeVisible();
    await expect(page.getByLabel(/הארנבת מקשיבה/).first()).toBeAttached();
    await ttsFirst;
    expectRabbitTexts(await visibleText(page));

    // 3. «להקשיב לסיפור» — осмотреть, дождаться следующего ответа tts (микрофон не включать)
    const ttsSecond = ttsResponse();
    await page.getByRole('button', { name: 'להקשיב לסיפור' }).click();
    await expect(page.getByText(/הארנבת מקריאה את הסיפור/)).toBeVisible();
    const stopButton = page.getByRole('button', { name: /עכשיו אני קוראת/ });
    await expect(stopButton).toBeVisible();
    expectRabbitTexts(await visibleText(page));
    await ttsSecond;

    // 4. «עזרה» (во время озвучки кнопка скрыта — останавливаем чтение, если оно ещё идёт)
    const helpButton = page.getByRole('button', { name: /^עזרה/ });
    await stopButton.or(helpButton).first().waitFor();
    if (await stopButton.isVisible()) {
      await stopButton.click();
    }
    await helpButton.click();
    await expect(page.getByText(/אותי קוראת/)).toBeVisible();
    expectRabbitTexts(await visibleText(page));

    // tts: все запросы voice === "rabbit", есть «אני מקשיבה», нет мужских форм
    expect(ttsBodies.length).toBeGreaterThanOrEqual(1);
    for (const b of ttsBodies) {
      expect(b.voice, `tts voice: ${JSON.stringify(b)}`).toBe('rabbit');
      expect(b.text ?? '').not.toMatch(/אני מקשיב(?!ה)/);
      expect(b.text ?? '').not.toMatch(/אני קורא(?!ת)/);
    }
    expect(ttsBodies.some((b) => (b.text ?? '').includes('אני מקשיבה'))).toBe(true);
  });
});
